def sieve_of_eratosthenes(max_n):
    """Generate a list of prime numbers up to max_n."""
    is_prime_list = [True] * (max_n + 1)
    p = 2
    while (p * p <= max_n):
        if (is_prime_list[p] == True):
            for i in range(p * p, max_n + 1, p):
                is_prime_list[i] = False
        p += 1
    prime_numbers = [p for p in range(2, max_n + 1) if is_prime_list[p]]
    return prime_numbers

