def solve(s):
    # Check if the string contains any letters
    has_letters = any(char.isalpha() for char in s)

    if has_letters:
        # If there are letters, reverse the case of each letter
        result = ''.join(char.swapcase() if char.isalpha() else char for char in s)
    else:
        # If there are no letters, reverse the entire string
        result = s[::-1]

    return result

