def solve(s):
    result = []
    has_letters = False

    for char in s:
        if char.isalpha():
            # Reverse the case of the letter
            if char.islower():
                result.append(char.upper())
            else:
                result.append(char.lower())
            has_letters = True
        else:
            # Keep the character as it is
            result.append(char)

    # If there are no letters, reverse the string
    if not has_letters:
        result = result[::-1]

    return ''.join(result)

