    vowel_map = {
        'a': 'c', 'A': 'C',
        'e': 'g', 'E': 'G',
        'i': 'k', 'I': 'K',
        'o': 'q', 'O': 'Q',
        'u': 'w', 'U': 'W'
    }

    # Initialize the encoded message as an empty string
    encoded_message = ''

    # Iterate over each character in the message
    for char in message:
        # If the character is a vowel, replace it with the corresponding character from the vowel_map
        if char in vowel_map:
            encoded_message += vowel_map[char]
        # If the character is a letter, swap its case
        elif char.isalpha():
            encoded_message += char.swapcase()
        else:
            # If the character is not a letter, add it unchanged
            encoded_message += char

    return encoded_message

