    vowels = 'aeiou'
    shifted_vowels = {vowels[i]: chr((ord(vowels[i]) - ord('a') + 2) % 26 + ord('a')) for i in range(len(vowels))}

    def swap_case_and_shift_vowel(c):
        if c.isalpha():
            if c.lower() in vowels:
                return shifted_vowels[c.lower()].upper() if c.islower() else shifted_vowels[c.lower()].lower()
            else:
                return c.swapcase()
        return c

    return ''.join(map(swap_case_and_shift_vowel, message))

